/* ---- overflow audit: every real content element must sit inside the card's padding box ---- */
const CONTENT = '.brand, .event, .title-wrap, .eyebrow, .title, .speaker, .avatar, .who, .name, .role, .footer, .meta, .when, .btn, .col-main, .col-side, .brand img, .avatar img';

function padBox() {
  const card = document.getElementById('card');
  const b = card.getBoundingClientRect();
  const cs = getComputedStyle(card);
  return {
    l: b.left + parseFloat(cs.paddingLeft),
    t: b.top + parseFloat(cs.paddingTop),
    r: b.right - parseFloat(cs.paddingRight),
    b: b.bottom - parseFloat(cs.paddingBottom)
  };
}

function overflows(tol) {
  tol = tol || 0.6;
  const p = padBox();
  const bad = [];
  document.querySelectorAll(CONTENT).forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) return;
    if (r.left < p.l - tol || r.right > p.r + tol || r.top < p.t - tol || r.bottom > p.b + tol) {
      bad.push(el.className || el.tagName);
    }
  });
  const inner = document.getElementById('inner');
  if (inner.scrollHeight > inner.clientHeight + tol) bad.push('inner-scroll');
  return bad;
}

document.fonts.ready.then(() => {
  const title = document.getElementById('title');
  let fs = parseFloat(getComputedStyle(title).fontSize);
  let guard = 0;
  // only the talk title is elastic; shrink it until the composition fits
  while (overflows().length && fs > 26 && guard++ < 300) {
    fs -= 1;
    title.style.fontSize = fs + 'px';
  }
  document.documentElement.setAttribute('data-ready', '1');
});

