input.function:
async () => {
  const names = ['square.png','landscape.png','story.png'];
  const out = {};
  for (const n of names) {
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = '/' + n + '?v=' + Date.now(); });
    out[n] = img.naturalWidth + 'x' + img.naturalHeight;
  }
  return out;
}

